static struct http_hdrflg * /* <=== http_hdr_flags */ 
http_hdr_flags(const char *b, const char *e)
{
	unsigned u;
	struct http_hdrflg *retval;

	if (e == NULL)
		return (NULL);
	assert(e > b);
	u = (unsigned)(e - b);
	assert(b + u == e);
	if (u < 2 || u > 19)		// MIN_WORD_LENGTH & MAX_WORD_LENGTH
		return (NULL);
	if (u > 3)
		u += http_asso_values[((const uint8_t*)b)[3]];
	if (u > 38)			// MAX_HASH_VALUE
		return (NULL);
	retval = &http_hdrflg[u];
	if (retval->hdr == NULL)
		return (NULL);
	if (!http_hdr_at(retval->hdr + 1, b, e - b))
		return (NULL);
	return (retval);
}

static inline int /* <=== vct_caselencmp */ 
vct_caselencmp(const void *a, const void *b, ssize_t sz)
{
	const uint8_t *aa = a;
	const uint8_t *bb = b;

	assert(sz >= 0);
	while (sz > 0 && *aa && vct_lowertab[*aa] == vct_lowertab[*bb]) {
		aa++;
		bb++;
		sz--;
	}
	if (!sz || (!*aa && !*bb))
		return (0);
	if (!*aa)
		return (-1);
	if (!*bb)
		return (1);
	return ((int)vct_lowertab[*aa] - (int)vct_lowertab[*bb]);
}

